-- PostgreSQL version of V3 (the H2 version is in ../h2). Same table, same columns, same constraints:
-- only the auto-numbered id is written the PostgreSQL way (BIGINT GENERATED BY DEFAULT AS IDENTITY).
--
-- Stock reservations: one row per (order, SKU) line that order-service asked inventory-service to hold.
--
-- Why this table exists: reserve and release must be safe to repeat. A call that timed out and is sent
-- again, or a release sent for a line that was never reserved, must not change the stock a second time.
-- The row remembers what was done for this order and SKU, so the second call can see it.
--
-- status is RESERVED (the units were taken from inventory_items) or RELEASED (they were put back).
-- The pair (order_id, sku_code) is unique: a line can be reserved once and released once, never twice.
-- order_id is the id of an order in order-service (another service with its own schema), so it is
-- NOT a database-level foreign key. sku_code is not a foreign key either (see V1).
CREATE TABLE IF NOT EXISTS stock_reservations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id BIGINT NOT NULL,
    sku_code VARCHAR(50) NOT NULL,
    quantity INT NOT NULL,
    status VARCHAR(20) NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Constraints
    CONSTRAINT uq_stock_reservations_order_sku UNIQUE (order_id, sku_code),
    CONSTRAINT chk_stock_reservations_status CHECK (status IN ('RESERVED', 'RELEASED')),
    CONSTRAINT chk_stock_reservations_quantity CHECK (quantity > 0)
);

-- Note: updated_at is maintained by Hibernate's @UpdateTimestamp and by the release query,
-- not by a DB-level trigger (same as inventory_items).
